const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.evaluate(() => localStorage.setItem('nine.best', '4200'));
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(900);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/check-menu.jpg', type: 'jpeg', quality: 70 });
  await page.click('#playBtn');
  await page.waitForTimeout(2600);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/check-play.jpg', type: 'jpeg', quality: 70 });
  console.log('DESKTOP', await page.evaluate(() => ({ state: __nine.game.state, p: Math.round(__nine.game.progress), lives: __nine.game.lives, sec: __nine.game.sector })));
  const m = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  m.on('pageerror', e => errors.push('m:' + e.message));
  await m.goto('http://localhost:3002', { waitUntil: 'load' });
  await m.waitForTimeout(900);
  await m.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/check-mobile-menu.jpg', type: 'jpeg', quality: 70 });
  await m.click('#playBtn');
  await m.waitForTimeout(2600);
  await m.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/check-mobile-play.jpg', type: 'jpeg', quality: 70 });
  console.log('MOBILE', await m.evaluate(() => ({ state: __nine.game.state, overflow: document.body.scrollWidth - innerWidth, p: Math.round(__nine.game.progress) })));
  console.log('ERRORS', JSON.stringify(errors));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

